%[text] # Design Temperature Controller for Data Center
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## Setup Model
%[text] This example models a 6 MW liquid-cooled data center represented by the **PDU + CDU Assembly (TL)** composite block. A chiller, cooling tower, and pumps complete the data center system from a thermal analysis perspective. For more information about parameterizing these blocks, see the [Create Liquid Cooled Data Center](file:../CreatePlantModels/CreateLiquidCooledDataCenterExample.m) example.
%[text] %[text:anchor:TMP_5ae1] Open the model.
modelParam.Model.Name = "DesignTemperatureControlForDataCenter";
open_system(modelParam.Model.Name);
%[text] Set the ambient temperature and relative humidity for this analysis.
modelParam.WetBulbT = simscape.Value(281,"K");
modelParam.relHumidity = 0.6;
%[text] Specify the temperature around the data center. This temperature is typically the room temperature at which the data center assets are housed. The room is maintained at a temperature suitable for human comfort.
modelParam.RoomT = simscape.Value(291,"K");
%[text] Specify the desired chiller outlet temperature to the cooling distribution unit (CDU) per ASHRAE guidelines.
modelParam.WaterSupplyTempCDU = simscape.Value(7,"degC");
%[text] Set up parameters for sizing the pumps.
setPumpParameters;
%%
%[text] ## Define Controls
%[text] The **Control** subsystem has two main components: the **CDU Control** and **Chiller and Pump Control** subsystems.
%[text] ### CDU Control
%[text] This subsystem controls these quantities in the CDU:
%[text] - Number of pumps, signal C.N
%[text] - Speed of pumps, signal C.S \
%[text] The pump speed increases linearly with the temperature difference between the server chip and the set-point temperature, normalized against the `Temperature window for no pumping` parameter. A PID controller determines the number of pumps to use. At least one pump is always on.
modelParam.NoPumpWindowT = 10; % Temperature window for no pumping
%[text] ### Chiller and Pump Control
%[text] - A PI controller controls the chiller. The control parameter is the difference between the measured and desired chiller outlet temperatures.
%[text] - A step function controls the condenser-side pump based on the temperature difference between the cooling tower inlet and outlet streams. The step size, set by the `Discrete temperature step control (degC)` parameter, is tunable. \
modelParam.StepControlTempr = 2; % Discrete temperature step control (degC)
%%
%[text] ## Run Simulation
%[text] ### Specify Design Options
%[text] This workflow evaluates the control parameters best suited for a favorable PUE. The parameter ranges considered in the design are:
%[text] - `Cold water temperature to CDU (degC)`: 7, 9 degC. \
designParam.ChillerOutletT = [7, 9];
%[text] - `Discrete temperature step control (degC)`: 2, 4 degC. \
designParam.StepControlT = [2, 4];
%[text] - `Temperature window for no pumping (K)`: 10, 20, 30 degC. \
designParam.NoPumpWindowT = [10, 20, 30];
%[text] Find all simulation scenarios.
designParam.desOptions = findFullFactorial({designParam.ChillerOutletT,...
                                            designParam.StepControlT,...
                                            designParam.NoPumpWindowT});
%[text] ### Run simulation
%[text] Run all design iterations and save the results in `designParam.desResults`.
designParam.desResults = zeros(size(designParam.desOptions,1),9);
for i = 1:size(designParam.desOptions,1)
    modelParam.WaterSupplyTempCDU = simscape.Value(designParam.desOptions(i,1),"degC");
    modelParam.StepControlTempr = designParam.desOptions(i,2);
    modelParam.NoPumpWindowT = designParam.desOptions(i,3);
    sim(modelParam.Model.Name);
    simResTbl = logsout_DesignTemperatureControllerDataCenter.extractTimetable;
    designParam.desResults(i,:) = ...
                [round(sum(simResTbl.("P.Cooling_Tower_Fan")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(sum(simResTbl.("P.Cooling_Tower_Pump")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(sum(simResTbl.("P.Chiller")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(sum(simResTbl.("P.CDU_External_Pump")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(sum(simResTbl.("P.PDU")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(sum(simResTbl.("P.CDU")(2:end).*diff(seconds(simResTbl.Time)))/(1000*seconds(simResTbl.Time(end))),2),...
                 round(mean(simResTbl.("T.Chip")(end-1200:end)),1),...
                 abs(round(mean(simResTbl.("T.CTa")(end-1200:end))-mean(simResTbl.("T.CTb")(end-1200:end)),1)),...
                 round(mean(simResTbl.PUE),3)...
                ];
end
close_system(modelParam.Model.Name,1);
%%
%[text] ## Analyze Results
%[text] Get result table for the full factorial set of simulation runs.
designParam.desResultTbl = ...
    array2table([designParam.desOptions,designParam.desResults],...
            VariableNames=["Chiller Outlet (degC)",...
                           "Step Control (degC)",...
                           "No Cooling Range (degC)",...
                           "Power: Cooling Tower Fan (kW)",...
                           "Power: Cooling Tower Pump (kW)",...
                           "Power: Chiller (kW)",...
                           "Power: CDU External Pump (kW)",...
                           "Power: PDU (kW)",...
                           "Power: CDU (kW)",...
                           "Server Temperature (K)",...
                           "Cooling Tower T-range (degC)",...
                           "PUE"]);
disp("*** All simulation case results table") %[output:752c43eb]
disp(designParam.desResultTbl); %[output:65a4e8b1]
%[text] Find the best scenario where the server temperature is maintain below a certain temperature and the PUE value is low.
designParam.desiredServerTmax = simscape.Value(325,"K");
%[text] Estimate best case.
listOfOpts  = designParam.desResultTbl.("Server Temperature (K)")<value(designParam.desiredServerTmax,"K");
listOfRuns = designParam.desResultTbl(listOfOpts,:);
[~,id] = min(listOfRuns.PUE) %[output:750f486e]

powerConsumptionCDU = ceil(listOfRuns(id,:).("Power: CDU (kW)")+listOfRuns(id,:).("Power: CDU External Pump (kW)"));
powerConsumptionFacilities = ceil(listOfRuns(id,:).("Power: Chiller (kW)") + ...
                                  listOfRuns(id,:).("Power: Cooling Tower Pump (kW)") + ...
                                  listOfRuns(id,:).("Power: Cooling Tower Fan (kW)"));
designParam.finalDesResult = rows2vars(listOfRuns(id,:));
disp(designParam.finalDesResult); %[output:3b3fcc47]
%[text] Display the CDU and facilities power consumption for the best case identified above.
piechart([listOfRuns(id,:).("Power: CDU (kW)"),... %[output:group:2b6a948f] %[output:78b36fb4]
          listOfRuns(id,:).("Power: Cooling Tower Pump (kW)"),... %[output:78b36fb4]
          listOfRuns(id,:).("Power: CDU External Pump (kW)"),... %[output:78b36fb4]
          listOfRuns(id,:).("Power: Cooling Tower Fan (kW)"),... %[output:78b36fb4]
          listOfRuns(id,:).("Power: Chiller (kW)")],... %[output:78b36fb4]
          ["CDU","Cooling Tower Pump","CDU External Pump","Cooling Tower Fan","Chiller"],... %[output:78b36fb4]
          Title=strcat("CDU (",num2str(powerConsumptionCDU)," kW) & Facilities (",num2str(powerConsumptionFacilities)," kW) Power Consumption")); %[output:group:2b6a948f] %[output:78b36fb4]
clear i id simResTbl logsout_DesignTemperatureControllerDataCenter listOfOpts listOfRuns
%[text] 

